#!/usr/bin/env python3
"""Writes docs/rules/data_sources.md: for every data folder, how many entries were checked against the free 2024
Basic Rules (source.checked_against) and which ones were entered from knowledge and still need a book check."""
import json
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FOLDERS = ["classes", "subclasses", "species", "backgrounds", "feats", "spells", "items", "magic_items", "monsters", "conditions"]


def main():
    lines = ["# Where the rules data comes from", "",
             "Generated by `python3 tools/data/data_sources.py`. **Checked** = every number compared with the free 2024",
             "Basic Rules on D&D Beyond (`source.checked_against: BR2024`). **From knowledge** = PHB/MM/CoS content the Basic",
             "Rules don't include, entered from knowledge of the books; these need a check against the owner's copy.",
             "**RtHW** (Ravenloft: The Horrors Within) entries were entered from the free 2025 Unearthed Arcana playtest",
             "(Horror Subclasses), published reviews of the book and Van Richten's Guide to Ravenloft, not from the book",
             "itself; every number needs a check against the owner's copy (each entry's `source.note` says what to check).", "",
             "| Data | Total | Checked | From knowledge |", "|---|---|---|---|"]
    unchecked = {}
    for folder in FOLDERS:
        entries = [json.loads(f.read_text()) for f in sorted((ROOT / "data" / folder).glob("*.json"))]
        checked = [e for e in entries if e.get("source", {}).get("checked_against")]
        rest = [e for e in entries if not e.get("source", {}).get("checked_against")]
        lines.append(f"| {folder} | {len(entries)} | {len(checked)} | {len(rest)} |")
        if rest:
            unchecked[folder] = rest
    lines += ["", "## Entries to check against the books", ""]
    for folder, rest in unchecked.items():
        by_book = defaultdict(list)
        for e in rest:
            by_book[e.get("source", {}).get("book", "?")].append(e.get("name", e["id"]))
        for book, names in by_book.items():
            lines.append(f"- **{folder}** ({book}, {len(names)}): " + ", ".join(sorted(names)))
    lines += ["", "## Magic items (DMG2024) entered from memory", "",
              "The 2024 Dungeon Master's Guide isn't in the free Basic Rules, so every magic item (data/magic_items, `book:",
              "DMG2024`) was entered from knowledge of the book (owner decision, personal use only): names, rarities,",
              "attunement, charges, DCs and effects all need a check against the owner's copy. The catalogue was rebuilt from",
              "memory as: every item of the 2014 DMG the 2024 book kept, the common items it folded in (from Xanathar's), the",
              "class implements (Amulet of the Devout, Arcane Grimoire, Bloodwell Vial, Moon Sickle, Rhythm-Maker's Drum,",
              "Dragonhide Belt, Wraps of Unarmed Power), Adamantine Weapon, and its artifacts. Left out as doubtful for the",
              "2024 book: the Sword of Answering, the All-Purpose Tool (Artificer only) and the Tasha's tattoos and shards.",
              "Artifacts' random properties use a condensed table (rules/equipment/magic_items.gd). The stat blocks for",
              "creatures the items summon (data/monsters) were since checked against SRD 5.2.1 (see Monster editions).",
              "Every item's `text`, `summary` and power text is written in our own words; only the game terms are the book's.",
              ""]
    lines += monster_editions()
    (ROOT / "docs/rules/data_sources.md").write_text("\n".join(lines))
    start = lines.index("| Data | Total | Checked | From knowledge |")
    print("\n".join(lines[start:start + len(FOLDERS) + 2]))


def monster_editions():
    """Owner rule (2026-10-06): a monster uses its 2025 Monster Manual block where one exists, else the 2014 one."""
    by = defaultdict(list)
    for f in sorted((ROOT / "data" / "monsters").glob("*.json")):
        e = json.loads(f.read_text())
        src = e.get("source", {})
        by[(src.get("edition", "?"), src.get("checked_against", "-"), src.get("book", "?"))].append(e.get("name", e["id"]))
    out = ["## Monster editions", "",
           "Owner rule: every monster uses its 2025 Monster Manual block (`source.edition: 2024`) where one exists, and",
           "the 2014 block (`2014`) only where there is no 2025 version (Curse of Strahd's own creatures and NPCs). SRD5.2 =",
           "compared line by line with the System Reference Document 5.2.1, whose monsters are the 2025 Monster Manual's.",
           "MM2025 entries still on 2014 numbers have a 2025 block that isn't in the SRD; they need the owner's book.", "",
           "| Edition | Checked against | Book | Count | Monsters |", "|---|---|---|---|---|"]
    for (ed, chk, book), names in sorted(by.items()):
        out.append(f"| {ed} | {chk} | {book} | {len(names)} | {', '.join(sorted(names))} |")
    return out + [""]


if __name__ == "__main__":
    main()
